const e={count:100,settings:{level:"Mixed",grammarFocus:["Mixed Grammar"],topics:["General"],lengthWords:[4,15],targetLang:"ru"},sentences:[{id:"1",text:"This is my book, and that one is yours.",translation:"Это моя книга, а та — твоя.",hint:{sentenceWithBlank:"This is my book, and that one is [____].",options:[{text:"yours",isCorrect:!0,explanation:"Абсолютная форма притяжательного местоимения (не требует существительного после себя)."},{text:"your",isCorrect:!1,explanation:"Требует существительного после себя (your book)."},{text:"you",isCorrect:!1,explanation:"Личное местоимение, а не притяжательное."}]},tense:"Present Simple",topic:"General",lengthWords:9},{id:"2",text:"He gave her his car because hers was broken.",translation:"Он отдал ей свою машину, потому что её сломалась.",hint:{sentenceWithBlank:"He gave her his car because [____] was broken.",options:[{text:"hers",isCorrect:!0,explanation:"Абсолютная форма притяжательного местоимения заменяет 'her car'."},{text:"her",isCorrect:!1,explanation:"Требует существительного после себя (her car)."},{text:"she",isCorrect:!1,explanation:"Личное местоимение (она), не показывает принадлежность."}]},tense:"Past Simple",topic:"General",lengthWords:9},{id:"3",text:"We did it ourselves without any help.",translation:"Мы сделали это сами без какой-либо помощи.",hint:{sentenceWithBlank:"We [____] [____] ourselves without any help.",options:[{text:"did it",isCorrect:!0,explanation:"Правильная форма прошедшего времени от 'do' и местоимение 'it'."},{text:"do it",isCorrect:!1,explanation:"Глагол в настоящем времени, а предложение о прошлом."},{text:"made it",isCorrect:!1,explanation:"Make означает 'создавать', а do - 'выполнять действие'."}]},tense:"Past Simple",topic:"General",lengthWords:7},{id:"4",text:"Is there anybody in the office?",translation:"Есть кто-нибудь в офисе?",hint:{sentenceWithBlank:"[____] there anybody in the office?",options:[{text:"Is",isCorrect:!0,explanation:"Глагол to be в ед.ч. для конструкции there is/are с anybody."},{text:"Are",isCorrect:!1,explanation:"Используется для множественного числа."},{text:"Does",isCorrect:!1,explanation:"Не используется в конструкции there is/are."}]},tense:"Present Simple",topic:"Workplace",lengthWords:6},{id:"5",text:"Nobody told me about the changes.",translation:"Никто не сказал мне об изменениях.",hint:{sentenceWithBlank:"Nobody [____] me about the changes.",options:[{text:"told",isCorrect:!0,explanation:"Утвердительная форма глагола в Past Simple. Отрицание уже есть в 'Nobody'."},{text:"didn't tell",isCorrect:!1,explanation:"В английском не бывает двойного отрицания (Nobody + didn't)."},{text:"said",isCorrect:!1,explanation:"Say не используется с прямым дополнением (me) без предлога to."}]},tense:"Past Simple",topic:"General",lengthWords:6},{id:"6",text:"This is the building whose roof was damaged.",translation:"Это здание, чья крыша была повреждена.",hint:{sentenceWithBlank:"This is the building [____] roof was damaged.",options:[{text:"whose",isCorrect:!0,explanation:"Относительное местоимение, обозначающее принадлежность (чей, чья, чье)."},{text:"who",isCorrect:!1,explanation:"Who означает 'кто', а не 'чей'."},{text:"which",isCorrect:!1,explanation:"Which (который) не выражает принадлежность."}]},tense:"Passive Voice",topic:"General",lengthWords:8},{id:"7",text:"Give it to him, not to them.",translation:"Отдай это ему, а не им.",hint:{sentenceWithBlank:"Give it to him, not to [____].",options:[{text:"them",isCorrect:!0,explanation:"Объектный падеж местоимения they (им, их)."},{text:"their",isCorrect:!1,explanation:"Притяжательное местоимение (их), требует существительного."},{text:"they",isCorrect:!1,explanation:"Именительный падеж (они), используется как подлежащее."}]},tense:"Imperative",topic:"General",lengthWords:7},{id:"8",text:"Both of them are busy right now.",translation:"Оба они сейчас заняты.",hint:{sentenceWithBlank:"[____] of them are busy right now.",options:[{text:"Both",isCorrect:!0,explanation:"Означает 'оба' (и тот, и другой)."},{text:"All",isCorrect:!1,explanation:"All (все) используется для трех и более человек или предметов."},{text:"Either",isCorrect:!1,explanation:"Either (любой из двух) требует глагола в единственном числе."}]},tense:"Present Simple",topic:"General",lengthWords:7},{id:"9",text:"Neither of the options is perfect.",translation:"Ни один из вариантов не идеален.",hint:{sentenceWithBlank:"[____] of the options is perfect.",options:[{text:"Neither",isCorrect:!0,explanation:"Означает 'ни один из двух'."},{text:"None",isCorrect:!1,explanation:"None используется для трех и более вариантов."},{text:"Both",isCorrect:!1,explanation:"Означает 'оба' и требует глагола во множественном числе (are)."}]},tense:"Present Simple",topic:"General",lengthWords:6},{id:"10",text:"Each component has its own function.",translation:"Каждый компонент имеет свою собственную функцию.",hint:{sentenceWithBlank:"Each component [____] its own function.",options:[{text:"has",isCorrect:!0,explanation:"Each (каждый) согласуется с глаголом в единственном числе."},{text:"have",isCorrect:!1,explanation:"Используется для множественного числа."},{text:"having",isCorrect:!1,explanation:"Герундий или причастие, здесь нужен сказуемое."}]},tense:"Present Simple",topic:"General",lengthWords:6},{id:"11",text:"She usually goes to work by bus, but today she is driving.",translation:"Она обычно ездит на работу на автобусе, но сегодня она за рулем.",hint:{sentenceWithBlank:"She usually goes to work by bus, but today she [____] [____].",options:[{text:"is driving",isCorrect:!0,explanation:"Present Continuous показывает временное действие, происходящее именно сегодня."},{text:"drives",isCorrect:!1,explanation:"Present Simple используется для регулярных действий (usually)."},{text:"driving",isCorrect:!1,explanation:"Пропущен вспомогательный глагол is."}]},tense:"Present Continuous",topic:"Daily Life",lengthWords:12},{id:"12",text:"Water boils at 100 degrees Celsius.",translation:"Вода кипит при 100 градусах Цельсия.",hint:{sentenceWithBlank:"Water [____] at 100 degrees Celsius.",options:[{text:"boils",isCorrect:!0,explanation:"Present Simple используется для общеизвестных фактов и законов природы."},{text:"is boiling",isCorrect:!1,explanation:"Present Continuous описывает действие прямо сейчас, а не факт."},{text:"boiled",isCorrect:!1,explanation:"Past Simple используется для действий в прошлом."}]},tense:"Present Simple",topic:"Science",lengthWords:6},{id:"13",text:"Does he know where the keys are?",translation:"Он знает, где ключи?",hint:{sentenceWithBlank:"[____] he know where the keys are?",options:[{text:"Does",isCorrect:!0,explanation:"Вспомогательный глагол для Present Simple (he, she, it)."},{text:"Do",isCorrect:!1,explanation:"Используется с I, you, we, they."},{text:"Is",isCorrect:!1,explanation:"Глагол to be не используется как вспомогательный со смысловым глаголом know."}]},tense:"Present Simple",topic:"Daily Life",lengthWords:7},{id:"14",text:"Why didn't you call me yesterday?",translation:"Почему ты не позвонил мне вчера?",hint:{sentenceWithBlank:"Why [____] you call me yesterday?",options:[{text:"didn't",isCorrect:!0,explanation:"Вспомогательный глагол для отрицательного вопроса в Past Simple."},{text:"don't",isCorrect:!1,explanation:"Это Present Simple, а в предложении есть указатель времени yesterday."},{text:"weren't",isCorrect:!1,explanation:"Глагол to be не используется со смысловым глаголом (call) в простом времени."}]},tense:"Past Simple",topic:"General",lengthWords:6},{id:"15",text:"I saw a great movie last weekend.",translation:"Я посмотрел отличный фильм на прошлых выходных.",hint:{sentenceWithBlank:"I [____] a great movie last weekend.",options:[{text:"saw",isCorrect:!0,explanation:"Past Simple (2 форма глагола see) для завершенного действия в прошлом (last weekend)."},{text:"see",isCorrect:!1,explanation:"Настоящее время, не подходит к last weekend."},{text:"have seen",isCorrect:!1,explanation:"Present Perfect не используется с точным указанием времени в прошлом."}]},tense:"Past Simple",topic:"Entertainment",lengthWords:7},{id:"16",text:"They didn't arrive on time because of the traffic.",translation:"Они не приехали вовремя из-за пробок.",hint:{sentenceWithBlank:"They didn't arrive on time [____] of the traffic.",options:[{text:"because",isCorrect:!0,explanation:"Because of (из-за) используется перед существительными."},{text:"why",isCorrect:!1,explanation:"Означает 'почему'."},{text:"as",isCorrect:!1,explanation:"As (так как) требует после себя полноценного предложения с подлежащим и сказуемым."}]},tense:"Past Simple",topic:"Travel",lengthWords:9},{id:"17",text:"What will you do if they reject the plan?",translation:"Что ты будешь делать, если они отклонят план?",hint:{sentenceWithBlank:"What [____] you do if they reject the plan?",options:[{text:"will",isCorrect:!0,explanation:"Future Simple в главной части условного предложения 1 типа (First Conditional)."},{text:"would",isCorrect:!1,explanation:"Используется во 2 типе условных предложений (нереальное условие)."},{text:"do",isCorrect:!1,explanation:"Тогда получится вопрос в настоящем времени 'Что ты делаешь (вообще)?'."}]},tense:"Future Simple",topic:"Workplace",lengthWords:9},{id:"18",text:"I think it will be a sunny day.",translation:"Думаю, день будет солнечным.",hint:{sentenceWithBlank:"I think it [____] [____] a sunny day.",options:[{text:"will be",isCorrect:!0,explanation:"Future Simple для предсказаний и личного мнения (I think)."},{text:"is being",isCorrect:!1,explanation:"Означает временное поведение в данный момент, не подходит по смыслу."},{text:"will",isCorrect:!1,explanation:"Не хватает смыслового глагола be (будет)."}]},tense:"Future Simple",topic:"General",lengthWords:8},{id:"19",text:"Are you going to update the layout this evening?",translation:"Ты собираешься обновить макет сегодня вечером?",hint:{sentenceWithBlank:"Are you [____] [____] update the layout this evening?",options:[{text:"going to",isCorrect:!0,explanation:"Конструкция to be going to используется для планов и намерений."},{text:"will to",isCorrect:!1,explanation:"После will частица to не ставится."},{text:"want to",isCorrect:!1,explanation:"Это переводилось бы как 'Ты хочешь...', а не 'Ты собираешься...'."}]},tense:"Future (going to)",topic:"IT",lengthWords:9},{id:"20",text:"The train leaves at 9 PM tonight.",translation:"Поезд отправляется сегодня в 9 вечера.",hint:{sentenceWithBlank:"The train [____] at 9 PM tonight.",options:[{text:"leaves",isCorrect:!0,explanation:"Present Simple используется для расписаний транспорта, даже в будущем."},{text:"will leave",isCorrect:!1,explanation:"С расписаниями принято использовать Present Simple."},{text:"is leaving",isCorrect:!1,explanation:"Используется для личных договоренностей, а не для расписания."}]},tense:"Present Simple",topic:"Travel",lengthWords:7},{id:"21",text:"How often do you practice your English?",translation:"Как часто ты практикуешь свой английский?",hint:{sentenceWithBlank:"How [____] do you practice your English?",options:[{text:"often",isCorrect:!0,explanation:"Вопросительное слово 'How often' (как часто) используется для вопросов о регулярности."},{text:"many",isCorrect:!1,explanation:"Означает 'как много' (для исчисляемых существительных)."},{text:"much",isCorrect:!1,explanation:"Означает 'как много' (для неисчисляемых существительных)."}]},tense:"Present Simple",topic:"Education",lengthWords:7},{id:"22",text:"Who wrote this article?",translation:"Кто написал эту статью?",hint:{sentenceWithBlank:"Who [____] this article?",options:[{text:"wrote",isCorrect:!0,explanation:"В вопросе к подлежащему вспомогательный глагол did не нужен. Используется прямой порядок слов."},{text:"did write",isCorrect:!1,explanation:"Неверная конструкция для вопроса к подлежащему (Who)."},{text:"written",isCorrect:!1,explanation:"Это 3 форма глагола, она требует вспомогательного глагола have/has."}]},tense:"Past Simple",topic:"General",lengthWords:4},{id:"23",text:"Who did you invite to the presentation?",translation:"Кого ты пригласил на презентацию?",hint:{sentenceWithBlank:"Who [____] you invite to the presentation?",options:[{text:"did",isCorrect:!0,explanation:"Вспомогательный глагол для вопроса в Past Simple (вопрос к дополнению - 'кого?')."},{text:"do",isCorrect:!1,explanation:"Настоящее время (кого ты приглашаешь обычно)."},{text:"were",isCorrect:!1,explanation:"Глагол to be не используется со смысловым глаголом invite в простом времени."}]},tense:"Past Simple",topic:"Workplace",lengthWords:7},{id:"24",text:"There used to be a cinema here.",translation:"Раньше здесь был кинотеатр.",hint:{sentenceWithBlank:"There [____] to be a cinema here.",options:[{text:"used",isCorrect:!0,explanation:"Конструкция 'used to' показывает то, что было раньше, но больше не существует."},{text:"use",isCorrect:!1,explanation:"Требуется прошедшее время (used)."},{text:"was",isCorrect:!1,explanation:"После was не может стоять инфинитив 'to be'."}]},tense:"Past Habit",topic:"General",lengthWords:7},{id:"25",text:"I am used to waking up early.",translation:"Я привык просыпаться рано.",hint:{sentenceWithBlank:"I am [____] [____] waking up early.",options:[{text:"used to",isCorrect:!0,explanation:"Конструкция 'to be used to + V-ing' означает привычку, сформированную к настоящему моменту."},{text:"use to",isCorrect:!1,explanation:"Для выражения привычки нужна форма used."},{text:"used",isCorrect:!1,explanation:"Пропущен предлог to, обязательный в этой конструкции."}]},tense:"Present Habit",topic:"Daily Life",lengthWords:7},{id:"26",text:"Look! It is snowing outside.",translation:"Смотри! На улице идет снег.",hint:{sentenceWithBlank:"Look! It [____] outside.",options:[{text:"is snowing",isCorrect:!0,explanation:"Present Continuous используется для действий, происходящих прямо сейчас (на что указывает 'Look!')."},{text:"snows",isCorrect:!1,explanation:"Present Simple означает регулярное действие, а не происходящее в данный момент."},{text:"snowing",isCorrect:!1,explanation:"Пропущен вспомогательный глагол 'is'."}]},tense:"Present Continuous",topic:"Nature",lengthWords:5},{id:"27",text:"What were you doing when I called you?",translation:"Что ты делал, когда я тебе позвонил?",hint:{sentenceWithBlank:"What [____] you [____] when I called you?",options:[{text:"were / doing",isCorrect:!0,explanation:"Past Continuous обозначает длительное действие в прошлом, прерванное другим действием (когда я позвонил)."},{text:"did / do",isCorrect:!1,explanation:"Past Simple используется для последовательных завершенных действий, а не для процесса."},{text:"are / doing",isCorrect:!1,explanation:"Present Continuous относится к настоящему, а здесь речь о прошлом ('when I called')."}]},tense:"Past Continuous",topic:"General",lengthWords:8},{id:"28",text:"While she was cooking, he was reading a book.",translation:"Пока она готовила, он читал книгу.",hint:{sentenceWithBlank:"While she [____], he was reading a book.",options:[{text:"was cooking",isCorrect:!0,explanation:"Past Continuous используется для одновременных длительных действий в прошлом."},{text:"cooked",isCorrect:!1,explanation:"Past Simple означает завершенное действие, но 'while' указывает на процесс."},{text:"is cooking",isCorrect:!1,explanation:"Вторая часть предложения в прошлом ('was reading'), поэтому и первая должна быть в прошедшем времени."}]},tense:"Past Continuous",topic:"Daily Life",lengthWords:9},{id:"29",text:"I have already finished the first task.",translation:"Я уже закончил первую задачу.",hint:{sentenceWithBlank:"I [____] already [____] the first task.",options:[{text:"have / finished",isCorrect:!0,explanation:"Present Perfect используется для завершенных действий с результатом в настоящем (маркер 'already')."},{text:"am / finishing",isCorrect:!1,explanation:"Present Continuous означает, что действие все еще происходит, а 'already' значит 'уже закончил'."},{text:"had / finished",isCorrect:!1,explanation:"Past Perfect нужен, когда есть другое действие в прошлом."}]},tense:"Present Perfect",topic:"Workplace",lengthWords:7},{id:"30",text:"Have you ever been to London?",translation:"Ты когда-нибудь был в Лондоне?",hint:{sentenceWithBlank:"Have you [____] been to London?",options:[{text:"ever",isCorrect:!0,explanation:"Слово 'ever' (когда-либо) часто используется в вопросах в Present Perfect для обсуждения жизненного опыта."},{text:"never",isCorrect:!1,explanation:"'never' означает 'никогда' и используется в утвердительных предложениях с отрицательным смыслом."},{text:"yet",isCorrect:!1,explanation:"'yet' ставится в конце предложения."}]},tense:"Present Perfect",topic:"Travel",lengthWords:6},{id:"31",text:"She has lived here since 2015.",translation:"Она живет здесь с 2015 года.",hint:{sentenceWithBlank:"She has lived here [____] 2015.",options:[{text:"since",isCorrect:!0,explanation:"'since' используется для указания конкретного момента начала действия в прошлом."},{text:"for",isCorrect:!1,explanation:"'for' указывает на продолжительность периода времени (например, for 5 years)."},{text:"from",isCorrect:!1,explanation:"'from' обычно требует парного предлога 'to' или 'until'."}]},tense:"Present Perfect",topic:"General",lengthWords:6},{id:"32",text:"We haven't seen each other for ages.",translation:"Мы не виделись целую вечность.",hint:{sentenceWithBlank:"We [____] each other for ages.",options:[{text:"haven't seen",isCorrect:!0,explanation:"Present Perfect показывает отсутствие действия с прошлого до настоящего времени ('for ages')."},{text:"didn't see",isCorrect:!1,explanation:"Past Simple указывает на завершенный период, а мы говорим о периоде, продолжающемся до сих пор."},{text:"don't see",isCorrect:!1,explanation:"Present Simple описывает регулярные действия, а не состояние 'с тех пор'."}]},tense:"Present Perfect",topic:"General",lengthWords:7},{id:"33",text:"When I arrived, the meeting had already started.",translation:"Когда я приехал, собрание уже началось.",hint:{sentenceWithBlank:"When I arrived, the meeting [____] already [____].",options:[{text:"had / started",isCorrect:!0,explanation:"Past Perfect показывает действие, которое завершилось до другого действия в прошлом ('When I arrived')."},{text:"has / started",isCorrect:!1,explanation:"Present Perfect не используется, если основное действие в прошлом ('arrived')."},{text:"was / starting",isCorrect:!1,explanation:"Это значило бы, что собрание только начиналось, а 'already' говорит о том, что оно уже началось."}]},tense:"Past Perfect",topic:"Workplace",lengthWords:8},{id:"34",text:"He realized he had lost his wallet.",translation:"Он понял, что потерял кошелек.",hint:{sentenceWithBlank:"He realized he [____] his wallet.",options:[{text:"had lost",isCorrect:!0,explanation:"Past Perfect используется для действия ('потерял'), которое произошло до другого действия в прошлом ('понял')."},{text:"loses",isCorrect:!1,explanation:"Present Simple не подходит по времени (главное предложение в прошедшем)."},{text:"has lost",isCorrect:!1,explanation:"Present Perfect связывает с настоящим, но осознание ('realized') было в прошлом."}]},tense:"Past Perfect",topic:"General",lengthWords:7},{id:"35",text:"By next year, they will have completed the project.",translation:"К следующему году они завершат проект.",hint:{sentenceWithBlank:"By next year, they [____] the project.",options:[{text:"will have completed",isCorrect:!0,explanation:"Future Perfect указывает на действие, которое завершится к определенному моменту в будущем ('By next year')."},{text:"will complete",isCorrect:!1,explanation:"Используется для фактов в будущем, но 'by' требует Future Perfect."},{text:"are completing",isCorrect:!1,explanation:"Present Continuous говорит о планах, но не передает идею завершенности к определенному моменту."}]},tense:"Future Perfect",topic:"Workplace",lengthWords:9},{id:"36",text:"I will be flying to Paris this time tomorrow.",translation:"Завтра в это время я буду лететь в Париж.",hint:{sentenceWithBlank:"I [____] to Paris this time tomorrow.",options:[{text:"will be flying",isCorrect:!0,explanation:"Future Continuous описывает процесс, который будет происходить в конкретный момент в будущем ('this time tomorrow')."},{text:"will fly",isCorrect:!1,explanation:"Future Simple обозначает просто факт или решение, а не процесс в определенный момент."},{text:"fly",isCorrect:!1,explanation:"Present Simple можно использовать для расписания, но здесь акцент на самом процессе полета."}]},tense:"Future Continuous",topic:"Travel",lengthWords:9},{id:"37",text:"This is the best coffee I have ever tasted.",translation:"Это лучший кофе, который я когда-либо пробовал.",hint:{sentenceWithBlank:"This is the best coffee I have [____] tasted.",options:[{text:"ever",isCorrect:!0,explanation:"'ever' используется для описания жизненного опыта, особенно после превосходной степени ('the best')."},{text:"never",isCorrect:!1,explanation:"'never' изменило бы смысл на 'никогда не пробовал'."},{text:"already",isCorrect:!1,explanation:"'already' означает 'уже', что не подходит к контексту 'лучший из всех'."}]},tense:"Present Perfect",topic:"Daily Life",lengthWords:9},{id:"38",text:"It's the first time I have driven an electric car.",translation:"Я впервые вожу электромобиль.",hint:{sentenceWithBlank:"It's the first time I [____] an electric car.",options:[{text:"have driven",isCorrect:!0,explanation:"Конструкция 'It's the first time...' всегда требует Present Perfect."},{text:"drive",isCorrect:!1,explanation:"Present Simple здесь не используется, так как это описание опыта."},{text:"drove",isCorrect:!1,explanation:"Past Simple используется для завершенных событий, но опыт актуален сейчас."}]},tense:"Present Perfect",topic:"General",lengthWords:10},{id:"39",text:"She was tired because she had worked all night.",translation:"Она устала, потому что работала всю ночь.",hint:{sentenceWithBlank:"She was tired because she [____] all night.",options:[{text:"had worked",isCorrect:!0,explanation:"Past Perfect объясняет причину ('работала') состояния в прошлом ('была уставшей')."},{text:"has worked",isCorrect:!1,explanation:"Present Perfect не подходит, так как результат ('была уставшей') находится в прошлом."},{text:"worked",isCorrect:!1,explanation:"Past Simple возможен, но Past Perfect лучше подчеркивает предшествование и причину."}]},tense:"Past Perfect",topic:"Daily Life",lengthWords:9},{id:"40",text:"I had never seen such a beautiful sunset before.",translation:"Я никогда раньше не видел такого красивого заката.",hint:{sentenceWithBlank:"I [____] seen such a beautiful sunset before.",options:[{text:"had never",isCorrect:!0,explanation:"Past Perfect подчеркивает, что этот опыт отсутствовал до определенного момента в прошлом."},{text:"have never",isCorrect:!1,explanation:"Present Perfect относится к настоящему, но 'before' указывает на момент в прошлом."},{text:"did never",isCorrect:!1,explanation:"Грамматически неверная конструкция (нужно 'never saw', но здесь нужен Past Perfect)."}]},tense:"Past Perfect",topic:"Nature",lengthWords:9},{id:"41",text:"I have been learning English for three years.",translation:"Я учу английский три года.",hint:{sentenceWithBlank:"I [____] English for three years.",options:[{text:"have been learning",isCorrect:!0,explanation:"Present Perfect Continuous подчеркивает длительность действия, которое началось в прошлом и продолжается сейчас."},{text:"am learning",isCorrect:!1,explanation:"Present Continuous не используется с указанием периода времени ('for three years')."},{text:"learn",isCorrect:!1,explanation:"Present Simple описывает факты, а не процесс, продолжающийся определенное время."}]},tense:"Present Perfect Continuous",topic:"Education",lengthWords:8},{id:"42",text:"Why are your hands dirty? — I've been fixing my bike.",translation:"Почему у тебя грязные руки? — Я чинил велосипед.",hint:{sentenceWithBlank:"Why are your hands dirty? — I've [____] my bike.",options:[{text:"been fixing",isCorrect:!0,explanation:"Present Perfect Continuous объясняет видимый результат в настоящем (грязные руки) недавним длительным процессом."},{text:"fixed",isCorrect:!1,explanation:"Present Perfect делает акцент на завершенности, но здесь важен сам процесс, оставивший следы."},{text:"fixing",isCorrect:!1,explanation:"Не хватает глагола 'been' для образования Present Perfect Continuous."}]},tense:"Present Perfect Continuous",topic:"Daily Life",lengthWords:11},{id:"43",text:"It has been raining all day.",translation:"Дождь идет весь день.",hint:{sentenceWithBlank:"It [____] all day.",options:[{text:"has been raining",isCorrect:!0,explanation:"Present Perfect Continuous для действия, которое длится с прошлого до настоящего момента ('all day')."},{text:"is raining",isCorrect:!1,explanation:"Present Continuous используется для момента 'сейчас', без указания длительности."},{text:"rains",isCorrect:!1,explanation:"Present Simple означает, что дождь идет вообще, а не непрерывно весь день."}]},tense:"Present Perfect Continuous",topic:"Nature",lengthWords:6},{id:"44",text:"She had been waiting for two hours before the bus arrived.",translation:"Она ждала два часа, прежде чем автобус приехал.",hint:{sentenceWithBlank:"She [____] for two hours before the bus arrived.",options:[{text:"had been waiting",isCorrect:!0,explanation:"Past Perfect Continuous показывает длительность действия до другого события в прошлом."},{text:"has been waiting",isCorrect:!1,explanation:"Present Perfect Continuous относится к настоящему, а здесь второе действие ('arrived') в прошлом."},{text:"was waiting",isCorrect:!1,explanation:"С предлогом 'for' (указание длительности) перед другим действием в прошлом нужен Past Perfect Continuous."}]},tense:"Past Perfect Continuous",topic:"Travel",lengthWords:11},{id:"45",text:"They had been living there for five years when the company closed.",translation:"Они жили там пять лет, когда компания закрылась.",hint:{sentenceWithBlank:"They [____] there for five years when the company closed.",options:[{text:"had been living",isCorrect:!0,explanation:"Past Perfect Continuous показывает, как долго длилось действие до определенного момента в прошлом."},{text:"were living",isCorrect:!1,explanation:"Past Continuous не используется, когда указана длительность ('for five years')."},{text:"have been living",isCorrect:!1,explanation:"События происходят в прошлом ('closed'), поэтому нужно прошедшее время."}]},tense:"Past Perfect Continuous",topic:"General",lengthWords:12},{id:"46",text:"His eyes were red because he had been staring at the screen for hours.",translation:"Его глаза были красными, потому что он часами смотрел в экран.",hint:{sentenceWithBlank:"His eyes were red because he [____] at the screen for hours.",options:[{text:"had been staring",isCorrect:!0,explanation:"Past Perfect Continuous используется для длительного процесса, который стал причиной состояния в прошлом."},{text:"has been staring",isCorrect:!1,explanation:"Следствие ('were red') находится в прошлом, поэтому нужно прошедшее время."},{text:"was staring",isCorrect:!1,explanation:"Past Continuous не передает идею предшествования и длительности, вызвавшей результат."}]},tense:"Past Perfect Continuous",topic:"Daily Life",lengthWords:14},{id:"47",text:"By midnight, I will have been working on this design for ten hours.",translation:"К полуночи я буду работать над этим дизайном уже десять часов.",hint:{sentenceWithBlank:"By midnight, I [____] on this design for ten hours.",options:[{text:"will have been working",isCorrect:!0,explanation:"Future Perfect Continuous показывает, как долго будет длиться действие к определенному моменту в будущем."},{text:"will work",isCorrect:!1,explanation:"Future Simple не передает длительность к моменту в будущем."},{text:"will be working",isCorrect:!1,explanation:"Future Continuous описывает процесс, но не подчеркивает его продолжительность ('for ten hours')."}]},tense:"Future Perfect Continuous",topic:"Workplace",lengthWords:13},{id:"48",text:"How long have you been looking for a job?",translation:"Как долго ты уже ищешь работу?",hint:{sentenceWithBlank:"How long [____] you [____] for a job?",options:[{text:"have / been looking",isCorrect:!0,explanation:"Вопросы с 'How long' о незаконченных действиях требуют Present Perfect Continuous."},{text:"are / looking",isCorrect:!1,explanation:"Present Continuous используется для вопроса о моменте речи ('что ты ищешь сейчас?'), а не 'как долго'."},{text:"do / look",isCorrect:!1,explanation:"Present Simple здесь не подходит, так как это не регулярное действие."}]},tense:"Present Perfect Continuous",topic:"General",lengthWords:9},{id:"49",text:"We had been driving for miles before we realized we were lost.",translation:"Мы ехали много миль, прежде чем поняли, что заблудились.",hint:{sentenceWithBlank:"We [____] for miles before we realized we were lost.",options:[{text:"had been driving",isCorrect:!0,explanation:"Past Perfect Continuous для процесса, который длился до определенного события в прошлом."},{text:"have been driving",isCorrect:!1,explanation:"Все события в предложении относятся к прошлому ('realized', 'were'), поэтому Present Perfect не подходит."},{text:"were driving",isCorrect:!1,explanation:"Past Continuous не подчеркивает накопленный результат и длительность до другого действия."}]},tense:"Past Perfect Continuous",topic:"Travel",lengthWords:12},{id:"50",text:"She has been running, so she is out of breath.",translation:"Она бежала, поэтому запыхалась.",hint:{sentenceWithBlank:"She [____], so she is out of breath.",options:[{text:"has been running",isCorrect:!0,explanation:"Present Perfect Continuous объясняет текущее состояние ('out of breath') недавним процессом."},{text:"is running",isCorrect:!1,explanation:"Present Continuous означает, что она бежит прямо сейчас."},{text:"ran",isCorrect:!1,explanation:"Past Simple фокусируется на факте бега, но Present Perfect Continuous лучше подчеркивает связь процесса с результатом."}]},tense:"Present Perfect Continuous",topic:"General",lengthWords:10},{id:"51",text:"You must wear a seatbelt while driving.",translation:"Вы обязаны пристегивать ремень безопасности во время вождения.",hint:{sentenceWithBlank:"You [____] wear a seatbelt while driving.",options:[{text:"must",isCorrect:!0,explanation:"Must выражает строгую обязанность или правило."},{text:"have",isCorrect:!1,explanation:"После have нужно использовать частицу to (have to)."},{text:"can",isCorrect:!1,explanation:"Can означает физическую возможность, а здесь речь о правиле."}]},tense:"Modal Verbs",topic:"Travel",lengthWords:7},{id:"52",text:"You don't have to pay for the tickets; they are free.",translation:"Тебе не обязательно платить за билеты, они бесплатные.",hint:{sentenceWithBlank:"You [____] pay for the tickets; they are free.",options:[{text:"don't have to",isCorrect:!0,explanation:"Don't have to означает отсутствие необходимости (не обязательно)."},{text:"mustn't",isCorrect:!1,explanation:"Mustn't означает строгий запрет (нельзя)."},{text:"shouldn't",isCorrect:!1,explanation:"Shouldn't — это совет (не следует), а здесь констатация факта об отсутствии нужды."}]},tense:"Modal Verbs",topic:"General",lengthWords:11},{id:"53",text:"You shouldn't eat so much fast food.",translation:"Тебе не следует есть так много фастфуда.",hint:{sentenceWithBlank:"You [____] eat so much fast food.",options:[{text:"shouldn't",isCorrect:!0,explanation:"Shouldn't используется для дачи совета (не следует)."},{text:"don't have to",isCorrect:!1,explanation:"Означает «не обязательно», не подходит по смыслу для совета."},{text:"can't",isCorrect:!1,explanation:"Can't выражает запрет или невозможность."}]},tense:"Modal Verbs",topic:"Daily Life",lengthWords:7},{id:"54",text:"He might come to the meeting, but he isn't sure.",translation:"Он может прийти на встречу, но он не уверен.",hint:{sentenceWithBlank:"He [____] come to the meeting, but he isn't sure.",options:[{text:"might",isCorrect:!0,explanation:"Might используется для выражения небольшой вероятности в будущем."},{text:"must",isCorrect:!1,explanation:"Must означает уверенность или обязанность."},{text:"can",isCorrect:!1,explanation:"Can обычно не используется для вероятности одиночных будущих действий."}]},tense:"Modal Verbs",topic:"Workplace",lengthWords:10},{id:"55",text:"May I borrow your pen for a moment?",translation:"Можно я одолжу твою ручку на минуту?",hint:{sentenceWithBlank:"[____] I borrow your pen for a moment?",options:[{text:"May",isCorrect:!0,explanation:"May используется для вежливой просьбы разрешения."},{text:"Must",isCorrect:!1,explanation:"Must используется для обязанности, а не для просьбы."},{text:"Should",isCorrect:!1,explanation:"Should — для совета (следует ли мне)."}]},tense:"Modal Verbs",topic:"General",lengthWords:8},{id:"56",text:"She can't be at home; I saw her at the office five minutes ago.",translation:"Она не может быть дома; я видел её в офисе пять минут назад.",hint:{sentenceWithBlank:"She [____] be at home; I saw her at the office five minutes ago.",options:[{text:"can't",isCorrect:!0,explanation:"Can't используется для выражения уверенности в том, что что-то невозможно."},{text:"mustn't",isCorrect:!1,explanation:"Mustn't означает строгий запрет, а не логическое умозаключение."},{text:"might not",isCorrect:!1,explanation:"Might not означает лишь небольшую вероятность, а здесь есть уверенность."}]},tense:"Modal Verbs",topic:"General",lengthWords:14},{id:"57",text:"He must have forgotten about our appointment.",translation:"Он, должно быть, забыл о нашей встрече.",hint:{sentenceWithBlank:"He [____] about our appointment.",options:[{text:"must have forgotten",isCorrect:!0,explanation:"Must + have + V3 выражает уверенное предположение о действии в прошлом."},{text:"must forget",isCorrect:!1,explanation:"Относится к настоящему или будущему времени."},{text:"should have forgotten",isCorrect:!1,explanation:"Означает «ему следовало забыть»."}]},tense:"Modal Verbs",topic:"General",lengthWords:7},{id:"58",text:"You should have told me the truth earlier.",translation:"Тебе следовало сказать мне правду раньше.",hint:{sentenceWithBlank:"You [____] me the truth earlier.",options:[{text:"should have told",isCorrect:!0,explanation:"Should + have + V3 используется для упрека о невыполненном действии в прошлом."},{text:"should tell",isCorrect:!1,explanation:"Относится к настоящему или будущему времени."},{text:"must have told",isCorrect:!1,explanation:"Означает уверенное предположение «ты, должно быть, сказал»."}]},tense:"Modal Verbs",topic:"General",lengthWords:8},{id:"59",text:"I could play the piano when I was a child.",translation:"Я умел играть на пианино, когда был ребенком.",hint:{sentenceWithBlank:"I [____] play the piano when I was a child.",options:[{text:"could",isCorrect:!0,explanation:"Could — форма прошедшего времени от can, используется для навыков в прошлом."},{text:"can",isCorrect:!1,explanation:"Can относится к настоящему времени."},{text:"must",isCorrect:!1,explanation:"Must означает обязанность, а не физическую способность."}]},tense:"Modal Verbs",topic:"General",lengthWords:10},{id:"60",text:"We had better leave now before it gets dark.",translation:"Нам лучше уйти сейчас, пока не потемнело.",hint:{sentenceWithBlank:"We [____] leave now before it gets dark.",options:[{text:"had better",isCorrect:!0,explanation:"Had better (лучше бы) используется для настоятельных советов или предупреждений."},{text:"would rather",isCorrect:!1,explanation:"Would rather означает предпочтение (предпочел бы)."},{text:"should to",isCorrect:!1,explanation:"После should не ставится частица to."}]},tense:"Modal Verbs",topic:"General",lengthWords:9},{id:"61",text:"If you heat ice, it melts.",translation:"Если нагреть лед, он тает.",hint:{sentenceWithBlank:"If you heat ice, it [____].",options:[{text:"melts",isCorrect:!0,explanation:"В Zero Conditional (общеизвестные факты) в обеих частях используется Present Simple."},{text:"will melt",isCorrect:!1,explanation:"Для научных фактов используется Present Simple, а не Future."},{text:"melted",isCorrect:!1,explanation:"Прошедшее время здесь не подходит."}]},tense:"Conditionals",topic:"Science",lengthWords:6},{id:"62",text:"If I have time tonight, I will call you.",translation:"Если у меня будет время сегодня вечером, я тебе позвоню.",hint:{sentenceWithBlank:"If I [____] time tonight, I [____] you.",options:[{text:"have / will call",isCorrect:!0,explanation:"First Conditional: условие в Present Simple (have), следствие в Future Simple (will call)."},{text:"will have / call",isCorrect:!1,explanation:"После if в условии не используется будущее время (will)."},{text:"had / would call",isCorrect:!1,explanation:"Это Second Conditional для нереальных ситуаций, а здесь реальное условие."}]},tense:"Conditionals",topic:"General",lengthWords:9},{id:"63",text:"Unless you study hard, you won't pass the exam.",translation:"Если ты не будешь усердно учиться, ты не сдашь экзамен.",hint:{sentenceWithBlank:"[____] you study hard, you won't pass the exam.",options:[{text:"Unless",isCorrect:!0,explanation:"Unless переводится как «если не» (if not) и уже содержит отрицание."},{text:"If",isCorrect:!1,explanation:"С if получилось бы «Если ты будешь учиться, ты не сдашь», что нелогично."},{text:"Without",isCorrect:!1,explanation:"Without — это предлог (без), после него должно идти существительное или герундий."}]},tense:"Conditionals",topic:"Education",lengthWords:9},{id:"64",text:"As soon as I arrive, I will let you know.",translation:"Как только я приеду, я дам тебе знать.",hint:{sentenceWithBlank:"[____] I arrive, I will let you know.",options:[{text:"As soon as",isCorrect:!0,explanation:"As soon as (как только) используется в придаточных времени с Present Simple."},{text:"Until",isCorrect:!1,explanation:"Until означает «до тех пор пока», что меняет смысл предложения."},{text:"While",isCorrect:!1,explanation:"While (в то время как) используется для длительных процессов."}]},tense:"Conditionals",topic:"General",lengthWords:10},{id:"65",text:"If I won the lottery, I would buy a house by the sea.",translation:"Если бы я выиграл в лотерею, я бы купил дом у моря.",hint:{sentenceWithBlank:"If I [____] the lottery, I [____] a house by the sea.",options:[{text:"won / would buy",isCorrect:!0,explanation:"Second Conditional: условие в Past Simple (won), следствие с would + инфинитив."},{text:"win / would buy",isCorrect:!1,explanation:"Слово win в настоящем времени не согласуется с would в главном предложении."},{text:"won / will buy",isCorrect:!1,explanation:"После Past Simple в условии используется would, а не will."}]},tense:"Conditionals",topic:"General",lengthWords:13},{id:"66",text:"What would you do if you were in my shoes?",translation:"Что бы ты сделал на моем месте?",hint:{sentenceWithBlank:"What [____] if you [____] in my shoes?",options:[{text:"would you do / were",isCorrect:!0,explanation:"Second Conditional: в вопросе would + инфинитив, в условии глагол to be в форме were для всех лиц."},{text:"will you do / are",isCorrect:!1,explanation:"Это First Conditional, а фраза 'in my shoes' предполагает гипотетическую ситуацию."},{text:"do you do / was",isCorrect:!1,explanation:"Неверная грамматика для условных предложений второго типа."}]},tense:"Conditionals",topic:"General",lengthWords:10},{id:"67",text:"If I had more free time, I would take up photography.",translation:"Если бы у меня было больше свободного времени, я бы занялся фотографией.",hint:{sentenceWithBlank:"If I [____] more free time, I [____] take up photography.",options:[{text:"had / would",isCorrect:!0,explanation:"Second Conditional: нереальное условие в настоящем (had), результат (would)."},{text:"have / will",isCorrect:!1,explanation:"Передает реальное условие, но здесь подчеркивается нереальность ситуации."},{text:"had had / would have",isCorrect:!1,explanation:"Это Third Conditional, относится к прошлому."}]},tense:"Conditionals",topic:"General",lengthWords:11},{id:"68",text:"If we had left earlier, we wouldn't have missed the flight.",translation:"Если бы мы выехали раньше, мы бы не опоздали на рейс.",hint:{sentenceWithBlank:"If we [____] earlier, we [____] the flight.",options:[{text:"had left / wouldn't have missed",isCorrect:!0,explanation:"Third Conditional: нереальное условие в прошлом (Past Perfect) и результат в прошлом (would have + V3)."},{text:"left / wouldn't miss",isCorrect:!1,explanation:"Это Second Conditional, относится к настоящему, а не к завершенному прошлому."},{text:"had left / wouldn't miss",isCorrect:!1,explanation:"Смешанный тип, не подходит по смыслу для обоих действий в прошлом."}]},tense:"Conditionals",topic:"Travel",lengthWords:11},{id:"69",text:"I wouldn't have known about the project if you hadn't told me.",translation:"Я бы не узнал о проекте, если бы ты мне не рассказал.",hint:{sentenceWithBlank:"I wouldn't [____] about the project if you hadn't told me.",options:[{text:"have known",isCorrect:!0,explanation:"Third Conditional: главное предложение строится с would have + V3 для ситуации в прошлом."},{text:"know",isCorrect:!1,explanation:"wouldn't know относится к настоящему времени."},{text:"knew",isCorrect:!1,explanation:"После would have должен идти глагол в 3-й форме (known), а не во второй."}]},tense:"Conditionals",topic:"General",lengthWords:12},{id:"70",text:"If I had studied harder at university, I would have a better job now.",translation:"Если бы я лучше учился в университете, у меня сейчас была бы работа получше.",hint:{sentenceWithBlank:"If I [____] harder at university, I [____] a better job now.",options:[{text:"had studied / would have",isCorrect:!0,explanation:"Mixed Conditional: условие в прошлом (Past Perfect), а следствие в настоящем (would + V1)."},{text:"studied / would have",isCorrect:!1,explanation:"Учеба в университете уже в прошлом, нужен Past Perfect."},{text:"had studied / would have had",isCorrect:!1,explanation:"Следствие относится к настоящему (now), поэтому would have, а не would have had."}]},tense:"Conditionals",topic:"Education",lengthWords:14},{id:"71",text:"If he spoke French, he would have translated that document yesterday.",translation:"Если бы он говорил по-французски, он бы перевел тот документ вчера.",hint:{sentenceWithBlank:"If he [____] French, he [____] that document yesterday.",options:[{text:"spoke / would have translated",isCorrect:!0,explanation:"Mixed Conditional: условие постоянно (Past Simple), а следствие было в прошлом (would have + V3)."},{text:"had spoken / would translate",isCorrect:!1,explanation:"Знание языка — постоянный факт, а перевод был вчера."},{text:"spoke / would translate",isCorrect:!1,explanation:"Перевод относится ко вчерашнему дню (yesterday), поэтому нужен would have + V3."}]},tense:"Conditionals",topic:"Workplace",lengthWords:11},{id:"72",text:"I wish I had more money.",translation:"Жаль, что у меня нет больше денег.",hint:{sentenceWithBlank:"I [____] I [____] more money.",options:[{text:"wish / had",isCorrect:!0,explanation:"Конструкция I wish + Past Simple используется для выражения сожаления о настоящем."},{text:"wish / have",isCorrect:!1,explanation:"После I wish для настоящего времени нужно использовать Past Simple."},{text:"hope / had",isCorrect:!1,explanation:"После hope обычно используется реальное время (настоящее или будущее)."}]},tense:"Conditionals",topic:"General",lengthWords:6},{id:"73",text:"I wish you wouldn't make so much noise.",translation:"Я бы хотел, чтобы ты не шумел так сильно.",hint:{sentenceWithBlank:"I wish you [____] make so much noise.",options:[{text:"wouldn't",isCorrect:!0,explanation:"I wish + would/wouldn't выражает раздражение чьим-то поведением в настоящем."},{text:"don't",isCorrect:!1,explanation:"После I wish не используется Present Simple."},{text:"didn't",isCorrect:!1,explanation:"didn't можно использовать, но wouldn't лучше подчеркивает раздражение действием другого."}]},tense:"Conditionals",topic:"General",lengthWords:8},{id:"74",text:"If only I hadn't said that to her yesterday.",translation:"Если бы только я не сказал ей это вчера.",hint:{sentenceWithBlank:"If [____] I [____] said that to her yesterday.",options:[{text:"only / hadn't",isCorrect:!0,explanation:"If only + Past Perfect выражает сильное сожаление о прошлом."},{text:"only / didn't",isCorrect:!1,explanation:"Действие было вчера, поэтому нужен Past Perfect, а не Past Simple."},{text:"just / haven't",isCorrect:!1,explanation:"If just не используется, а haven't — это Present Perfect, не подходит для вчера."}]},tense:"Conditionals",topic:"General",lengthWords:9},{id:"75",text:"It's time we went home.",translation:"Пора нам идти домой.",hint:{sentenceWithBlank:"It's time we [____] home.",options:[{text:"went",isCorrect:!0,explanation:"После конструкции It's time (давно пора) используется форма Past Simple."},{text:"go",isCorrect:!1,explanation:"Для выражения It's time + подлежащее глагол ставится в Past Simple, а не в начальную форму."},{text:"are going",isCorrect:!1,explanation:"Настоящее длительное время здесь не используется."}]},tense:"Conditionals",topic:"General",lengthWords:5},{id:"76",text:"This house was built in 1920.",translation:"Этот дом был построен в 1920 году.",hint:{sentenceWithBlank:"This house [____] in 1920.",options:[{text:"was built",isCorrect:!0,explanation:"Пассивный залог в прошедшем времени (Past Simple Passive) используется для указания на действие в прошлом над объектом."},{text:"built",isCorrect:!1,explanation:"Здесь нужен пассивный залог, так как дом не сам себя строил."},{text:"is built",isCorrect:!1,explanation:"Действие произошло в прошлом (в 1920 году), поэтому нужно прошедшее время."}]},tense:"Passive Voice",topic:"General",lengthWords:6},{id:"77",text:"The interface is being redesigned at the moment.",translation:"Интерфейс сейчас перерабатывается.",hint:{sentenceWithBlank:"The interface [____] at the moment.",options:[{text:"is being redesigned",isCorrect:!0,explanation:"Present Continuous Passive используется для действия, которое происходит прямо сейчас (at the moment)."},{text:"is redesigned",isCorrect:!1,explanation:"Present Simple Passive указывает на регулярное действие, а не происходящее в данный момент."},{text:"has been redesigned",isCorrect:!1,explanation:"Это Present Perfect Passive, означает уже завершенное действие."}]},tense:"Passive Voice",topic:"IT",lengthWords:8},{id:"78",text:"The new software has just been installed.",translation:"Новое ПО только что было установлено.",hint:{sentenceWithBlank:"The new software [____].",options:[{text:"has just been installed",isCorrect:!0,explanation:"Present Perfect Passive используется для недавно завершенного действия (с 'just')."},{text:"has just installed",isCorrect:!1,explanation:"ПО не может установить само себя, нужен пассивный залог."},{text:"was just installed",isCorrect:!1,explanation:"С наречием 'just' обычно используется Present Perfect, а не Past Simple."}]},tense:"Passive Voice",topic:"IT",lengthWords:7},{id:"79",text:"English is spoken all over the world.",translation:"На английском говорят по всему миру.",hint:{sentenceWithBlank:"English [____] all over the world.",options:[{text:"is spoken",isCorrect:!0,explanation:"Present Simple Passive используется для общеизвестных фактов."},{text:"is speaking",isCorrect:!1,explanation:"Язык не может говорить сам по себе, нужен пассивный залог."},{text:"spoke",isCorrect:!1,explanation:"Это активный залог в прошедшем времени."}]},tense:"Passive Voice",topic:"General",lengthWords:7},{id:"80",text:"The letters will be sent tomorrow morning.",translation:"Письма будут отправлены завтра утром.",hint:{sentenceWithBlank:"The letters [____] tomorrow morning.",options:[{text:"will be sent",isCorrect:!0,explanation:"Future Simple Passive используется для действия над объектом в будущем."},{text:"will send",isCorrect:!1,explanation:"Письма не могут отправить сами себя (нужен пассив)."},{text:"are sent",isCorrect:!1,explanation:"Это Present Simple Passive, а действие произойдет завтра."}]},tense:"Passive Voice",topic:"General",lengthWords:7},{id:"81",text:"I need to get my hair cut this week.",translation:"Мне нужно подстричься на этой неделе.",hint:{sentenceWithBlank:"I need to [____] this week.",options:[{text:"get my hair cut",isCorrect:!0,explanation:"Конструкция 'get/have something done' означает, что действие выполняется кем-то другим для вас."},{text:"cut my hair",isCorrect:!1,explanation:"Это означало бы, что вы сами собираетесь стричь себе волосы."},{text:"get cutting my hair",isCorrect:!1,explanation:"Грамматически неверная конструкция."}]},tense:"Passive Voice",topic:"Daily Life",lengthWords:9},{id:"82",text:"He had his laptop stolen while he was traveling.",translation:"У него украли ноутбук во время путешествия.",hint:{sentenceWithBlank:"He [____] while he was traveling.",options:[{text:"had his laptop stolen",isCorrect:!0,explanation:"Конструкция 'have something done' может использоваться для негативного опыта (кто-то украл его ноутбук)."},{text:"stole his laptop",isCorrect:!1,explanation:"Это означает, что он сам украл свой ноутбук."},{text:"had stolen his laptop",isCorrect:!1,explanation:"Past Perfect в активном залоге: он украл свой ноутбук до какого-то момента."}]},tense:"Passive Voice",topic:"General",lengthWords:9},{id:"83",text:"She was made to clean the whole room by her mother.",translation:"Мама заставила её убрать всю комнату.",hint:{sentenceWithBlank:"She [____] to clean the whole room by her mother.",options:[{text:"was made",isCorrect:!0,explanation:"В пассивном залоге глагол 'make' в значении 'заставлять' требует частицу 'to' перед следующим глаголом."},{text:"made",isCorrect:!1,explanation:"Активный залог изменит смысл: 'Она заставила'."},{text:"has made",isCorrect:!1,explanation:"Тоже активный залог, но в Present Perfect."}]},tense:"Passive Voice",topic:"Daily Life",lengthWords:11},{id:"84",text:"He is said to be the richest man in the city.",translation:"Говорят, он самый богатый человек в городе.",hint:{sentenceWithBlank:"He [____] to be the richest man in the city.",options:[{text:"is said",isCorrect:!0,explanation:"Пассивная конструкция 'is said to' переводится как 'говорят, что он...'."},{text:"says",isCorrect:!1,explanation:"Это означало бы 'Он говорит, что является самым богатым...'."},{text:"said",isCorrect:!1,explanation:"Прошедшее время 'Он сказал' - нарушает структуру предложения."}]},tense:"Passive Voice",topic:"General",lengthWords:11},{id:"85",text:"It is expected that the prices will drop soon.",translation:"Ожидается, что цены скоро упадут.",hint:{sentenceWithBlank:"[____] that the prices will drop soon.",options:[{text:"It is expected",isCorrect:!0,explanation:"Безличная пассивная конструкция используется для выражения общего мнения/ожидания."},{text:"It expects",isCorrect:!1,explanation:"Слово 'It' не может ничего 'ожидать' (нужен пассив)."},{text:"They is expected",isCorrect:!1,explanation:"Грамматически неверно: с 'They' используется 'are', но здесь нужно безличное 'It'."}]},tense:"Passive Voice",topic:"General",lengthWords:9},{id:"86",text:"He said that he was working on a new project.",translation:"Он сказал, что работает над новым проектом.",hint:{sentenceWithBlank:"He said that he [____] on a new project.",options:[{text:"was working",isCorrect:!0,explanation:"По правилу согласования времен, Present Continuous из прямой речи переходит в Past Continuous."},{text:"is working",isCorrect:!1,explanation:"Так как главное предложение в прошедшем ('said'), зависимое должно согласоваться по времени."},{text:"works",isCorrect:!1,explanation:"Означает постоянное действие (Present Simple), нарушает согласование времен."}]},tense:"Reported Speech",topic:"Workplace",lengthWords:10},{id:"87",text:"She told me she had already seen that movie.",translation:"Она сказала мне, что уже видела этот фильм.",hint:{sentenceWithBlank:"She [____] me she had already seen that movie.",options:[{text:"told",isCorrect:!0,explanation:"Глагол 'tell' всегда требует прямого дополнения (кому сказали - 'me')."},{text:"said",isCorrect:!1,explanation:"После 'said' нужен предлог 'to', если указывается кому: 'said to me'."},{text:"spoke",isCorrect:!1,explanation:"'Speak' означает 'говорить на языке' или 'разговаривать с кем-то', не вводит косвенную речь."}]},tense:"Reported Speech",topic:"Entertainment",lengthWords:9},{id:"88",text:"They said they would help us the following week.",translation:"Они сказали, что помогут нам на следующей неделе.",hint:{sentenceWithBlank:"They said they [____] help us the following week.",options:[{text:"would",isCorrect:!0,explanation:"При согласовании времен 'will' (будущее время) заменяется на 'would'."},{text:"will",isCorrect:!1,explanation:"Нарушение правила согласования времен, так как главное предложение в прошедшем."},{text:"should",isCorrect:!1,explanation:"Изменит смысл на 'следует/должны помочь', а не просто будущее действие."}]},tense:"Reported Speech",topic:"General",lengthWords:9},{id:"89",text:"He asked me where I lived.",translation:"Он спросил меня, где я живу.",hint:{sentenceWithBlank:"He asked me where [____].",options:[{text:"I lived",isCorrect:!0,explanation:"В косвенном вопросе используется прямой порядок слов и согласование времен."},{text:"did I live",isCorrect:!1,explanation:"Вспомогательный глагол не нужен, так как это косвенный вопрос, а не прямой."},{text:"I live",isCorrect:!1,explanation:"Нарушено согласование времен (главное предложение в прошедшем времени - asked)."}]},tense:"Reported Speech",topic:"General",lengthWords:6},{id:"90",text:"She asked if I could help her with the task.",translation:"Она спросила, могу ли я помочь ей с заданием.",hint:{sentenceWithBlank:"She asked [____] I could help her with the task.",options:[{text:"if",isCorrect:!0,explanation:"Для общих вопросов (без вопросительного слова) в косвенной речи используются 'if' или 'whether'."},{text:"that",isCorrect:!1,explanation:"Слово 'that' используется для утверждений, а не для вопросов."},{text:"can",isCorrect:!1,explanation:"Грамматически не подходит по структуре."}]},tense:"Reported Speech",topic:"General",lengthWords:10},{id:"91",text:"The manager advised me to review the guidelines.",translation:"Менеджер посоветовал мне изучить руководство.",hint:{sentenceWithBlank:"The manager advised me [____] the guidelines.",options:[{text:"to review",isCorrect:!0,explanation:"После глаголов типа 'advise', 'ask', 'tell' используется инфинитив с частицей 'to'."},{text:"reviewing",isCorrect:!1,explanation:"Герундий не используется после 'advise' + лицо."},{text:"review",isCorrect:!1,explanation:"Пропущена частица 'to', необходимая для инфинитива."}]},tense:"Reported Speech",topic:"Workplace",lengthWords:8},{id:"92",text:"He denied making that mistake.",translation:"Он отрицал, что совершил ту ошибку.",hint:{sentenceWithBlank:"He denied [____] that mistake.",options:[{text:"making",isCorrect:!0,explanation:"После глагола 'deny' используется герундий (V-ing)."},{text:"to make",isCorrect:!1,explanation:"Инфинитив после 'deny' не используется."},{text:"make",isCorrect:!1,explanation:"Грамматически неверная форма."}]},tense:"Reported Speech",topic:"General",lengthWords:5},{id:"93",text:"She promised not to tell anyone his secret.",translation:"Она обещала никому не говорить его секрет.",hint:{sentenceWithBlank:"She promised [____] anyone his secret.",options:[{text:"not to tell",isCorrect:!0,explanation:"Отрицательная форма инфинитива образуется добавлением 'not' перед 'to'."},{text:"to not tell",isCorrect:!1,explanation:"Не совсем корректный порядок слов для стандартной грамматики."},{text:"don't tell",isCorrect:!1,explanation:"Здесь нужен инфинитив, а не повелительное наклонение."}]},tense:"Reported Speech",topic:"General",lengthWords:8},{id:"94",text:"Although it was raining, we went for a walk.",translation:"Хотя шел дождь, мы пошли на прогулку.",hint:{sentenceWithBlank:"[____] it was raining, we went for a walk.",options:[{text:"Although",isCorrect:!0,explanation:"Союз 'although' (хотя) используется перед подлежащим и сказуемым."},{text:"Despite",isCorrect:!1,explanation:"После 'despite' должно идти существительное или герундий, а не полноценное предложение (it was raining)."},{text:"However",isCorrect:!1,explanation:"Обычно используется как вводное слово и выделяется запятой."}]},tense:"Conjunctions",topic:"General",lengthWords:9},{id:"95",text:"Despite the heavy traffic, we arrived on time.",translation:"Несмотря на пробки, мы приехали вовремя.",hint:{sentenceWithBlank:"[____] the heavy traffic, we arrived on time.",options:[{text:"Despite",isCorrect:!0,explanation:"'Despite' (несмотря на) используется с существительным или герундием."},{text:"Although",isCorrect:!1,explanation:"После 'although' должно идти полноценное предложение (подлежащее + сказуемое)."},{text:"In spite",isCorrect:!1,explanation:"Требует предлога 'of' (In spite of)."}]},tense:"Conjunctions",topic:"Travel",lengthWords:8},{id:"96",text:"Seldom have I seen such a beautiful piece of art.",translation:"Редко я видел такое красивое произведение искусства.",hint:{sentenceWithBlank:"[____] such a beautiful piece of art.",options:[{text:"Seldom have I seen",isCorrect:!0,explanation:"В начале предложения отрицательные/ограничительные наречия (seldom) требуют инверсии (обратного порядка слов)."},{text:"Seldom I have seen",isCorrect:!1,explanation:"После 'seldom' в начале предложения требуется инверсия (порядок как в вопросе)."},{text:"Have I seldom seen",isCorrect:!1,explanation:"Наречие 'seldom' должно стоять первым."}]},tense:"Inversion",topic:"General",lengthWords:10},{id:"97",text:"No sooner had I closed the door than the phone rang.",translation:"Не успел я закрыть дверь, как зазвонил телефон.",hint:{sentenceWithBlank:"[____] closed the door than the phone rang.",options:[{text:"No sooner had I",isCorrect:!0,explanation:"Конструкция 'No sooner + инверсия (had I) ... than' означает 'не успел я..., как...'."},{text:"No sooner I had",isCorrect:!1,explanation:"После 'No sooner' обязательна инверсия вспомогательного глагола и подлежащего."},{text:"As soon as I had",isCorrect:!1,explanation:"Конструкция 'As soon as' не сочетается с 'than' во второй части предложения."}]},tense:"Inversion",topic:"General",lengthWords:11},{id:"98",text:"I look forward to hearing from you soon.",translation:"С нетерпением жду ответа от вас в ближайшее время.",hint:{sentenceWithBlank:"I look forward [____] from you soon.",options:[{text:"to hearing",isCorrect:!0,explanation:"В выражении 'look forward to' слово 'to' является предлогом, поэтому после него нужен герундий (V-ing)."},{text:"to hear",isCorrect:!1,explanation:"Здесь 'to' — не часть инфинитива, а предлог, поэтому нужен герундий."},{text:"hearing",isCorrect:!1,explanation:"Пропущен обязательный предлог 'to'."}]},tense:"Gerund",topic:"Workplace",lengthWords:8},{id:"99",text:"It's no use crying over spilled milk.",translation:"Слезами горю не поможешь. / Нет смысла плакать над пролитым молоком.",hint:{sentenceWithBlank:"It's no use [____] over spilled milk.",options:[{text:"crying",isCorrect:!0,explanation:"После выражения 'it's no use' (нет смысла) всегда используется герундий."},{text:"to cry",isCorrect:!1,explanation:"Инфинитив в данной идиоме не используется."},{text:"cry",isCorrect:!1,explanation:"Грамматически неверная форма, нужен герундий."}]},tense:"Gerund",topic:"General",lengthWords:7},{id:"100",text:"Not only did he design the layout, but he also wrote the code.",translation:"Он не только разработал макет, но и написал код.",hint:{sentenceWithBlank:"Not only [____] the layout, but he also wrote the code.",options:[{text:"did he design",isCorrect:!0,explanation:"Когда предложение начинается с 'Not only', применяется инверсия (порядок слов как в вопросе)."},{text:"he designed",isCorrect:!1,explanation:"Отсутствует инверсия, которая обязательна после 'Not only' в начале."},{text:"designed he",isCorrect:!1,explanation:"Инверсия делается с помощью вспомогательного глагола 'did', а не основного глагола."}]},tense:"Inversion",topic:"IT",lengthWords:13}]};export{e as builtInPack};
